import{_ as a,o as r,c as o,ag as l}from"./chunks/framework.OsDJF_Ea.js";const g=JSON.parse('{"title":"프로젝트","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/projects.md","filePath":"02-user-guide/projects.md","lastUpdated":1776993543000}'),e={name:"02-user-guide/projects.md"};function i(n,t,d,s,h,u){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="프로젝트" tabindex="-1">프로젝트 <a class="header-anchor" href="#프로젝트" aria-label="Permalink to &quot;프로젝트&quot;">​</a></h1><p>프로젝트는 Workhub의 핵심 업무 단위입니다. 프로젝트 안에 <strong>토픽</strong>(주제별 논의)을 만들고, 각 토픽에서 메시지와 태스크를 관리합니다.</p><h2 id="프로젝트-목록" tabindex="-1">프로젝트 목록 <a class="header-anchor" href="#프로젝트-목록" aria-label="Permalink to &quot;프로젝트 목록&quot;">​</a></h2><p>사이드바 &gt; <strong>프로젝트</strong>를 클릭하면 참여 중인 프로젝트 목록이 표시됩니다.</p><h3 id="프로젝트-그룹" tabindex="-1">프로젝트 그룹 <a class="header-anchor" href="#프로젝트-그룹" aria-label="Permalink to &quot;프로젝트 그룹&quot;">​</a></h3><p>프로젝트를 그룹으로 분류하여 관리할 수 있습니다:</p><ol><li>프로젝트 목록에서 <strong>&quot;+ 그룹 만들기&quot;</strong> 버튼을 클릭합니다.</li><li>그룹 이름을 입력합니다.</li><li>프로젝트를 그룹에 포함시키거나 이동할 수 있습니다.</li><li>그룹 공개 설정: <strong>관리자만 보기</strong> 또는 <strong>전체 공개</strong>를 선택할 수 있습니다.</li></ol><h2 id="프로젝트-생성" tabindex="-1">프로젝트 생성 <a class="header-anchor" href="#프로젝트-생성" aria-label="Permalink to &quot;프로젝트 생성&quot;">​</a></h2><ol><li>프로젝트 목록 화면에서 <strong>&quot;+ 프로젝트 만들기&quot;</strong> 버튼을 클릭합니다.</li><li>프로젝트 이름과 설명을 입력합니다.</li><li><strong>토픽 정책</strong>을 선택합니다: <ul><li><code>필수</code>: 모든 메시지가 토픽 단위로 관리됩니다.</li><li><code>선택</code>: 토픽 없이도 사용 가능합니다.</li></ul></li></ol><h2 id="프로젝트-상세" tabindex="-1">프로젝트 상세 <a class="header-anchor" href="#프로젝트-상세" aria-label="Permalink to &quot;프로젝트 상세&quot;">​</a></h2><p>프로젝트를 클릭하면 다음 정보를 확인할 수 있습니다:</p><ul><li><strong>토픽 목록</strong>: 프로젝트 내 토픽들</li><li><strong>구성원</strong>: 프로젝트 참여자 목록</li><li><strong>프로젝트 설정</strong>: 이름, 설명 수정</li></ul><h2 id="토픽" tabindex="-1">토픽 <a class="header-anchor" href="#토픽" aria-label="Permalink to &quot;토픽&quot;">​</a></h2><p>토픽은 프로젝트 내의 주제별 논의 공간입니다.</p><h3 id="토픽-생성" tabindex="-1">토픽 생성 <a class="header-anchor" href="#토픽-생성" aria-label="Permalink to &quot;토픽 생성&quot;">​</a></h3><ol><li>프로젝트 상세 화면에서 <strong>&quot;+ 토픽 만들기&quot;</strong> 버튼을 클릭합니다.</li><li>토픽 이름과 설명을 입력합니다.</li></ol><h3 id="토픽-상태" tabindex="-1">토픽 상태 <a class="header-anchor" href="#토픽-상태" aria-label="Permalink to &quot;토픽 상태&quot;">​</a></h3><table tabindex="0"><thead><tr><th>상태</th><th>설명</th></tr></thead><tbody><tr><td>진행중</td><td>현재 활동 중인 토픽</td></tr><tr><td>완료</td><td>목적을 달성한 토픽</td></tr><tr><td>보관</td><td>더 이상 사용하지 않는 토픽</td></tr></tbody></table><h3 id="토픽-상세" tabindex="-1">토픽 상세 <a class="header-anchor" href="#토픽-상세" aria-label="Permalink to &quot;토픽 상세&quot;">​</a></h3><p>토픽을 클릭하면 두 개의 탭이 표시됩니다:</p><ul><li><strong>메시지</strong> 탭: 토픽 내 대화, 쓰레드, 리액션</li><li><strong>태스크</strong> 탭: 칸반 보드 또는 간트 차트 뷰</li></ul><h2 id="프로젝트-구성원" tabindex="-1">프로젝트 구성원 <a class="header-anchor" href="#프로젝트-구성원" aria-label="Permalink to &quot;프로젝트 구성원&quot;">​</a></h2><h3 id="역할" tabindex="-1">역할 <a class="header-anchor" href="#역할" aria-label="Permalink to &quot;역할&quot;">​</a></h3><table tabindex="0"><thead><tr><th>역할</th><th>권한</th></tr></thead><tbody><tr><td>admin</td><td>프로젝트 설정, 구성원 관리, 보관</td></tr><tr><td>member</td><td>토픽 생성, 메시지, 태스크</td></tr><tr><td>guest</td><td>읽기 전용</td></tr></tbody></table><h3 id="구성원-초대" tabindex="-1">구성원 초대 <a class="header-anchor" href="#구성원-초대" aria-label="Permalink to &quot;구성원 초대&quot;">​</a></h3><p>프로젝트 관리자(admin)가 프로젝트 상세 &gt; 구성원 섹션에서 사용자를 초대합니다.</p><h2 id="토픽-이동-병합" tabindex="-1">토픽 이동 / 병합 <a class="header-anchor" href="#토픽-이동-병합" aria-label="Permalink to &quot;토픽 이동 / 병합&quot;">​</a></h2><p>기관 관리자 또는 프로젝트 관리자는 토픽을 다른 프로젝트로 이동하거나 다른 토픽과 병합할 수 있습니다.</p><h3 id="토픽-이동" tabindex="-1">토픽 이동 <a class="header-anchor" href="#토픽-이동" aria-label="Permalink to &quot;토픽 이동&quot;">​</a></h3><ol><li>토픽 설정 메뉴에서 **&quot;토픽 이동&quot;**을 선택합니다.</li><li>이동할 대상 프로젝트를 선택합니다.</li><li>이동 전 미리보기에서 영향받는 태스크와 의존성을 확인합니다.</li><li>다른 프로젝트의 태스크와 의존성이 있는 경우 경고가 표시됩니다.</li></ol><h3 id="토픽-병합" tabindex="-1">토픽 병합 <a class="header-anchor" href="#토픽-병합" aria-label="Permalink to &quot;토픽 병합&quot;">​</a></h3><ol><li>토픽 설정 메뉴에서 **&quot;토픽 병합&quot;**을 선택합니다.</li><li>병합 대상 토픽을 선택합니다.</li><li>원본 토픽의 메시지와 태스크가 대상 토픽으로 합쳐집니다.</li></ol><h2 id="프로젝트-보관-삭제" tabindex="-1">프로젝트 보관 / 삭제 <a class="header-anchor" href="#프로젝트-보관-삭제" aria-label="Permalink to &quot;프로젝트 보관 / 삭제&quot;">​</a></h2><h3 id="보관" tabindex="-1">보관 <a class="header-anchor" href="#보관" aria-label="Permalink to &quot;보관&quot;">​</a></h3><p>프로젝트를 보관하면 <strong>읽기 전용</strong> 상태가 됩니다. 메시지와 태스크를 조회할 수 있지만 새로운 작성은 불가합니다.</p><h3 id="삭제" tabindex="-1">삭제 <a class="header-anchor" href="#삭제" aria-label="Permalink to &quot;삭제&quot;">​</a></h3><p>프로젝트 삭제 전 영향받는 토픽, 태스크, 메시지, 파일 수가 표시됩니다. 확인을 위해 <strong>프로젝트 이름을 직접 입력</strong>해야 합니다. 삭제된 프로젝트는 기관 관리자의 <strong>보관함</strong>에서 확인할 수 있습니다.</p><p><strong>삭제 권한:</strong></p><ul><li>프로젝트 개설자(owner)</li><li>기관 관리자(org_admin) / 시스템 관리자(system_admin)</li></ul><h2 id="토픽-삭제" tabindex="-1">토픽 삭제 <a class="header-anchor" href="#토픽-삭제" aria-label="Permalink to &quot;토픽 삭제&quot;">​</a></h2><p>프로젝트 상세 화면의 토픽 목록에서 각 토픽 항목에 마우스를 올리면 <strong>휴지통 아이콘</strong>이 나타납니다.</p><ol><li>휴지통 아이콘을 클릭합니다.</li><li>영향받는 <strong>태스크 수</strong>와 <strong>메시지 수</strong>가 표시됩니다.</li><li>확인을 위해 <strong>토픽 이름을 직접 입력</strong>합니다.</li><li>&quot;영구 삭제&quot; 버튼을 클릭합니다.</li></ol><p><strong>삭제 권한:</strong></p><ul><li>토픽 생성자</li><li>프로젝트 개설자</li><li>기관 관리자(org_admin) / 시스템 관리자(system_admin)</li></ul><blockquote><p>일반 멤버는 휴지통 아이콘이 표시되지 않아 삭제 버튼을 볼 수 없습니다.</p></blockquote>',45)])])}const b=a(e,[["render",i]]);export{g as __pageData,b as default};
